typedef long long int ll;
typedef pair<ll, ll> pr;

#include <atcoder/modint>
using mint = atcoder::modint998244353;

ll x1, x2, x3;

vector<mint> frac, invf;
void f_init (const ll n) {
	frac.resize(n+1);
	invf.resize(n+1);

	frac[0] = 1;
	for (ll i = 1; i <= n; i++) {
		frac[i] = frac[i-1] * i;
	}
	invf[n] = frac[n].inv();
	for (ll i = n; i >= 1; i--) {
		invf[i-1] = invf[i] * i;
	}
}
mint ncr (ll n, ll r) {
	if (n < 0 || n < r) return 0;
	return frac[n] * invf[r] * invf[n-r];
}
mint part1 (ll x, ll p) {
	return ncr(x-1, p-1);
}

void solve () {
	f_init(x1 + x2 + x3 + 10);

	mint ans = 0;

	// 13131...1
	for (ll i = 2; i <= x1; i++) {
		ans += part1(x1, i) * part1(x3, i-1) * ncr(x1+x2+x3 - (i*2-2), x1 + x3);
	}
	// 31313...3
	for (ll i = 2; i <= x3; i++) {
		ans += part1(x3, i) * part1(x1, i-1) * ncr(x1+x2+x3 - (i*2-2), x1 + x3);
	}
	// 1313...13, 3131...31
	for (ll i = 1; i <= min(x1, x3); i++) {
		ans += 2 * part1(x1, i) * part1(x3, i) * ncr(x1+x2+x3 - (i*2-1), x1 + x3);
	}

	cout << ans.val() << "\n";
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> x1 >> x2 >> x3;

	solve();


	return 0;
}

#include <bits/stdc++.h>
#include <atcoder/convolution>
using namespace std;
using namespace atcoder;

using mint = modint998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int X1, X2, X3;
    cin >> X1 >> X2 >> X3;

    int N = max({X1, X2 + 1, X3}) + 5;

    vector<mint> fact(N), ifact(N);

    fact[0] = 1;

    for (int i = 1; i < N; i++) {
        fact[i] = fact[i - 1] * i;
    }

    ifact[N - 1] = fact[N - 1].inv();

    for (int i = N - 1; i >= 1; i--) {
        ifact[i - 1] = ifact[i] * i;
    }

    auto C = [&](int n, int k) -> mint {
        if (k < 0 || k > n) return 0;
        return fact[n] * ifact[k] * ifact[n - k];
    };

    vector<mint> A(X1 + 1), B(X3 + 1);

    for (int p = 1; p <= X1; p++) {
        A[p] = C(X1 - 1, p - 1) * ifact[p];
    }

    for (int q = 1; q <= X3; q++) {
        B[q] = C(X3 - 1, q - 1) * ifact[q];
    }

    vector<mint> conv = convolution(A, B);

    mint ans = 0;

    for (int s = 0; s <= X2 + 1 && s < (int)conv.size(); s++) {
        ans += C(X2 + 1, s) * fact[s] * conv[s];
    }

    cout << ans.val() << '\n';
}
